{"revisions": [
  {"original_name": "IS_PLAN", "operation": "KEEP"},
  {"original_name": "ACTION_IMPLEMENTS_PLANNED_STEP", "operation": "KEEP"},
  {"original_name": "DIAGNOSES_OBSERVED_ARTIFACT_DEFECT", "operation": "KEEP"},
  {
    "original_name": "PROPOSES_CONCRETE_REMEDIATION",
    "operation": "REVISE",
    "revised_predicate": {
      "name": "PROPOSES_CONCRETE_REMEDIATION",
      "definition": "The reasoning specifies a concrete correction, completion, or remediation for an identified defect, gap, unmet requirement, or underlying persistence or causal mechanism, including replacement content, configuration changes, or steps intended to make the target satisfy the requirement or remove the mechanism.",
      "parameters": [
        {
          "name": "remediation_reasoning",
          "type": "reasoning",
          "description": "The reasoning containing the proposed concrete remediation, completion, or cause-directed correction."
        }
      ],
      "assertion_conditions": [
        "The reasoning identifies at least one concrete change, replacement, added step, or intervention intended to repair, complete, remedy, or remove an identified defect, gap, unmet requirement, or underlying persistence or causal mechanism.",
        "The proposed remediation is tied to the identified defect, gap, requirement, or mechanism rather than being a generic intention to fix or improve something."
      ],
      "exclusion_conditions": [
        "The reasoning only identifies a defect, gap, or mechanism without proposing how to repair, complete, or remove it.",
        "The reasoning expresses only a generic intention to fix or improve without concrete content or steps.",
        "The proposed change is unrelated to the identified defect, gap, requirement, or mechanism.",
        "The reasoning only reports that remediation was performed without proposing the remediation."
      ]
    }
  },
  {"original_name": "PROBES_CAPABILITY_AVAILABILITY", "operation": "KEEP"},
  {"original_name": "IMPLEMENTS_SPECIFIED_CHANGE", "operation": "KEEP"},
  {
    "original_name": "PRODUCES_EXPECTED_DERIVED_OUTPUT",
    "operation": "REVISE",
    "revised_predicate": {
      "name": "PRODUCES_EXPECTED_DERIVED_OUTPUT",
      "definition": "An action invokes a transformation, derivation, or generation process on source input, and its observation provides evidence that the expected derived artifact or output was produced.",
      "parameters": [
        {
          "name": "transformation_action",
          "type": "action",
          "description": "The action that runs the transformation, derivation, or generation process."
        },
        {
          "name": "generation_observation",
          "type": "observation",
          "description": "The observation reporting generation or existence of the expected derived output."
        }
      ],
      "assertion_conditions": [
        "The action invokes a transformation, derivation, or generation process on a source input.",
        "The observation provides evidence that the expected derived artifact or output was produced or exists after the step."
      ],
      "exclusion_conditions": [
        "The action only inspects files or inputs without invoking a transformation or generation step.",
        "The observation does not show that the expected derived artifact or output was generated.",
        "The transformation or generation reports an error preventing output production."
      ]
    }
  },
  {
    "original_name": "DIAGNOSES_ACTION_FAILURE_FROM_ERROR",
    "operation": "REVISE",
    "revised_predicate": {
      "name": "DIAGNOSES_ACTION_FAILURE_FROM_ERROR",
      "definition": "The reasoning interprets an error or non-success result reported by an observation and identifies a specific cause or a condition that a corrected attempt must satisfy, where the identified cause is tied to the details of the reported failure rather than merely restating the error or generically attributing it to the target functionality.",
      "parameters": [
        {
          "name": "diagnosis_reasoning",
          "type": "reasoning",
          "description": "The reasoning that interprets the failure and identifies its specific cause or required correction."
        },
        {
          "name": "error_observation",
          "type": "observation",
          "description": "The observation reporting the error or non-success result."
        }
      ],
      "assertion_conditions": [
        "The observation reports an error or otherwise unsuccessful result from a prior action.",
        "The reasoning identifies a cause, misunderstood condition, or requirement for a corrected attempt.",
        "The identified cause or requirement is consistent with the specific details of the reported error rather than a generic assertion that the target functionality is broken."
      ],
      "exclusion_conditions": [
        "The reasoning merely repeats the error message without interpreting its cause or implications.",
        "The reasoning retries the same operation without identifying any corrective condition.",
        "The reasoning attributes the failure to the target functionality without tying that attribution to the observed error details.",
        "The observation does not report an error or failure."
      ]
    }
  },
  {"original_name": "CORRECTS_FAILED_ACTION_WITH_DIAGNOSED_REVISION", "operation": "KEEP"},
  {"original_name": "CONCLUDES_TASK_SUCCESS_FROM_ACCUMULATED_EVIDENCE", "operation": "KEEP"},
  {"original_name": "EVALUATES_ALTERNATIVES", "operation": "KEEP"},
  {
    "original_name": "IS_STATE_PROBE",
    "operation": "REVISE",
    "revised_predicate": {
      "name": "IS_STATE_PROBE",
      "definition": "The action is a read-only inspection of system, environment, or artifact state carried out to obtain information, without altering that state.",
      "parameters": [
        {
          "name": "probe_action",
          "type": "action",
          "description": "The action that inspects rather than modifies system or artifact state."
        }
      ],
      "assertion_conditions": [
        "The action consists of informational query or inspection operations that read system, environment, or artifact state.",
        "The action's own description or command composition shows an informational purpose and contains no persistent modification of the inspected state."
      ],
      "exclusion_conditions": [
        "The action installs, creates, deletes, or reconfigures resources.",
        "An inspection command appears only incidentally inside an action whose purpose is a persistent change.",
        "The action executes a change and merely reports its own output."
      ]
    }
  },
  {"original_name": "TESTS_ASSUMPTION_WITH_PROBE", "operation": "KEEP"},
  {"original_name": "GROUNDS_CONCLUSION_IN_OBSERVATION", "operation": "KEEP"},
  {"original_name": "ADAPTS_PLAN_TO_OBSERVED_STATE", "operation": "KEEP"},
  {"original_name": "MITIGATES_ANTICIPATED_FAILURE", "operation": "KEEP"},
  {"original_name": "VALIDATES_PRECONDITION_BEFORE_DEPENDENT_ACTION", "operation": "KEEP"},
  {"original_name": "VERIFIES_EXPECTED_OUTCOME", "operation": "KEEP"},
  {
    "original_name": "CLASSIFIES_FAILURE_AS_TEST_ARTIFACT",
    "operation": "REVISE",
    "revised_predicate": {
      "name": "CLASSIFIES_APPARENT_RESULT_AS_CONTEXT_ARTIFACT",
      "definition": "The reasoning explains an observed failure, anomaly, misleading or empty result, or apparent match or candidate as an artifact of the agent's own test setup, execution context, tooling, measurement technique, or incidental contextual material rather than as evidence about the genuine target condition.",
      "parameters": [
        {
          "name": "assessment_reasoning",
          "type": "reasoning",
          "description": "The reasoning classifying the observed result as an artifact of setup, context, tooling, measurement technique, or incidental material."
        },
        {
          "name": "observed_result",
          "type": "observation",
          "description": "The observation reporting the failure, anomaly, misleading or empty result, or apparent match or candidate."
        }
      ],
      "assertion_conditions": [
        "The observation reports a failure, error, anomaly, empty or misleading result, or apparent match or candidate relevant to the sought condition.",
        "The reasoning attributes that result to the agent's own test setup, execution context, tooling, measurement technique, or incidental contextual or unrelated origin.",
        "The reasoning distinguishes this artifact from genuine evidence about the target condition, such as a genuine defect, limitation, or match."
      ],
      "exclusion_conditions": [
        "The reasoning treats the result as a genuine defect or limitation of the target system or as a genuine match.",
        "The reasoning only restates the result or identifies a cause without classifying it as an artifact of setup, context, tooling, measurement, or incidental material.",
        "The observation does not report a failure, anomaly, misleading or empty result, or apparent match or candidate."
      ]
    }
  },
  {"original_name": "SUCCESSFUL_CORRECTIVE_RETRY", "operation": "KEEP"},
  {"original_name": "PLANS_MULTI_CRITERIA_VERIFICATION", "operation": "KEEP"},
  {"original_name": "AUDITS_PLANNED_CRITERIA", "operation": "KEEP"},
  {"original_name": "ASSESSES_ANOMALY_AS_NON_IMPACTING", "operation": "KEEP"},
  {
    "original_name": "DECODES_ENCODED_OBSERVATION",
    "operation": "REVISE",
    "revised_predicate": {
      "name": "DECODES_ENCODED_OBSERVATION",
      "definition": "The reasoning translates low-level, encoded, or machine-oriented fields returned by an observation into domain-level states or meanings, and the stated conclusion depends on that translation.",
      "parameters": [
        {
          "name": "interpretation_reasoning",
          "type": "reasoning",
          "description": "The agent text mapping raw fields to domain-level meanings."
        },
        {
          "name": "encoded_observation",
          "type": "observation",
          "description": "The observation whose content is in an encoded, low-level, or machine-oriented form."
        }
      ],
      "

